"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { useSearchParams } from "next/navigation";
import { useLocale } from "next-intl";
import { ProductGrid } from "@/components/productCard/ProductGrid";
import NavigateButtons from "@/components/navigateButtons/NavigateButtons";
import { useUIStore } from "@/store/zustand/useUIStore";
import { fetchNearbyListings, fetchProductsPaginated } from "@/app/actions/nearby-listings";
import type { InitialProductStateType } from "@/types/product.types";
import type { NearbyCursor, NearbyPost } from "@/lib/data/nearby-posts";

/** Hard cap on radius expansion. Beyond this the feed is considered exhausted. */
const MAX_RADIUS_METERS = 50000; // 50km

/** Format distance for display - miles for US (en), km for others */
function formatDistance(meters: number, locale: string): string {
  if (locale === "en") {
    const miles = meters / 1609.34;
    return `${Math.round(miles)} miles`;
  }
  const km = meters / 1000;
  return `${Math.round(km)} km`;
}

/**
 * Next radius step during expansion. Doubles each time, capped at MAX_RADIUS.
 * 5km → 10km → 20km → 40km → 50km → done.
 */
function nextRadiusStep(currentRadius: number): number {
  return Math.min(currentRadius * 2, MAX_RADIUS_METERS);
}

interface HomeClientProps {
  initialProducts: InitialProductStateType[];
  productType?: string;
  /** Nearby posts with distance (when location filter is active) */
  nearbyPosts?: NearbyPost[] | null;
  /** Whether location filter is currently active */
  isLocationFiltered?: boolean;
  /** Current radius in meters */
  radiusMeters?: number;
  /** Whether more pages are available (from server) */
  initialHasMore?: boolean;
  /** Keyset cursor for next page (from server) */
  initialNextCursor?: NearbyCursor | null;
}

// Default search radius in meters (passed as prop, falls back to 5km if not provided)

/**
 * HomeClient - Client wrapper for the home page
 * Automatically detects user location and shows nearby posts
 *
 * Flow:
 * 1. On mount, check if URL already has location params (server-rendered with nearby data)
 * 2. If not, request browser geolocation automatically
 * 3. Once location is obtained, fetch nearby posts via Server Action (no server re-render)
 * 4. Update URL with history.replaceState for shareability (no navigation)
 * 5. Infinite scroll loads more pages via Server Actions
 */
export function HomeClient({
  initialProducts,
  productType = "food",
  nearbyPosts,
  isLocationFiltered = false,
  radiusMeters = 5000,
  initialHasMore = false,
  initialNextCursor = null,
}: HomeClientProps) {
  const searchParams = useSearchParams();
  const locale = useLocale();

  // Get stored location from Zustand (persisted across sessions)
  const userLocation = useUIStore((state) => state.userLocation);
  const setUserLocation = useUIStore((state) => state.setUserLocation);
  const geoDistance = useUIStore((state) => state.geoDistance);

  // Client-side nearby posts state (populated after geolocation detection)
  const [clientNearbyPosts, setClientNearbyPosts] = useState<NearbyPost[] | null>(null);
  const [isClientLocationFiltered, setIsClientLocationFiltered] = useState(false);
  // Track the *display* radius: the user's configured radius at first load.
  // Used only for the "Nothing shared within X" empty message, so it reflects
  // the genuine local radius, not the grown expansion radius.
  const [displayRadius, setDisplayRadius] = useState(radiusMeters);
  const [isFetchingNearby, setIsFetchingNearby] = useState(false);

  // Pagination state. Two disjoint cursor schemes coexist because the two fetch
  // paths are mutually exclusive per session:
  //   - nearbyCursor: keyset (distance, id) for location-mode
  //   - productsCursor: integer id for non-location mode
  // Only one is ever active depending on effectiveIsLocationFiltered.
  const [extraProducts, setExtraProducts] = useState<InitialProductStateType[]>([]);
  const [hasMore, setHasMore] = useState(initialHasMore);
  const [nearbyCursor, setNearbyCursor] = useState<NearbyCursor | null>(
    isLocationFiltered ? initialNextCursor : null
  );
  const [productsCursor, setProductsCursor] = useState<number | null>(
    isLocationFiltered ? null : (initialNextCursor as unknown as number | null)
  );
  const [isFetchingMore, setIsFetchingMore] = useState(false);
  // True once at least one load-more has fired. Gates the "Nothing shared"
  // message to initial load only, so it never reflects the expansion radius.
  const [hasAttemptedLoadMore, setHasAttemptedLoadMore] = useState(false);

  // Track location + the *currently-active query radius* for nearby fetching.
  // queryRadius grows during expansion; displayRadius (state) stays at the user's
  // configured value for messaging. Keeping queryRadius in a ref avoids stale
  // closures inside handleLoadMore without adding it to the dependency array
  // on every render.
  const locationRef = useRef<{ lat: number; lng: number; queryRadius: number } | null>(
    isLocationFiltered && searchParams.has("lat") && searchParams.has("lng")
      ? {
          lat: parseFloat(searchParams.get("lat") as string),
          lng: parseFloat(searchParams.get("lng") as string),
          queryRadius: searchParams.has("radius")
            ? parseInt(searchParams.get("radius") as string, 10)
            : radiusMeters,
        }
      : null
  );

  // Use server-rendered nearby posts if available, otherwise use client-fetched ones
  const effectiveNearbyPosts = isLocationFiltered ? nearbyPosts : clientNearbyPosts;
  const effectiveIsLocationFiltered = isLocationFiltered || isClientLocationFiltered;

  const baseProducts =
    effectiveIsLocationFiltered && effectiveNearbyPosts
      ? (effectiveNearbyPosts as unknown as InitialProductStateType[])
      : initialProducts;

  // Combine base products with extra pages loaded via infinite scroll
  const products = [...baseProducts, ...extraProducts];

  // Fetch nearby posts via Server Action (no server re-render)
  const fetchNearby = useCallback(
    async (lat: number, lng: number, radius: number, postType: string) => {
      setIsFetchingNearby(true);
      try {
        const result = await fetchNearbyListings({ lat, lng, radius, postType });
        if (result.success) {
          setClientNearbyPosts(result.data);
          setIsClientLocationFiltered(true);
          // displayRadius captures the user's configured radius at first load.
          setDisplayRadius(radius);
          setHasMore(result.hasMore);
          setNearbyCursor(result.nextCursor);
          setProductsCursor(null);
          setExtraProducts([]);
          setHasAttemptedLoadMore(false);
          locationRef.current = { lat, lng, queryRadius: radius };
        }
      } finally {
        setIsFetchingNearby(false);
      }
    },
    []
  );

  const effectiveHasMore = hasMore;

  /**
   * Append newly fetched nearby posts, deduping by id against everything
   * already shown (base + extras). Returns nothing; updates extraProducts.
   */
  const appendDeduped = useCallback(
    (incoming: NearbyPost[]) => {
      setExtraProducts((prev) => {
        const existingIds = new Set([...baseProducts, ...prev].map((p) => p.id));
        const newProducts = (incoming as unknown as InitialProductStateType[]).filter(
          (p) => !existingIds.has(p.id)
        );
        return [...prev, ...newProducts];
      });
    },
    [baseProducts]
  );

  /**
   * Load more products (infinite scroll).
   *
   * Location mode uses keyset pagination over (distance_meters, id). When a
   * radius tier is exhausted (hasMore=false) we EXPAND the search radius
   * (doubling, capped at 50km) and re-query with the SAME keyset cursor.
   * Because the keyset predicate excludes every already-seen row regardless of
   * radius, expansion can only add farther items — no dupes, no skips, and the
   * ORDER BY stays globally consistent.
   */
  const handleLoadMore = useCallback(async () => {
    if (isFetchingMore) return;

    // Location mode: keyset pagination with radius expansion on drain.
    if (effectiveIsLocationFiltered && locationRef.current) {
      const canPageCurrentTier = hasMore && nearbyCursor !== null;
      const atRadiusCap = locationRef.current.queryRadius >= MAX_RADIUS_METERS;
      if (!canPageCurrentTier && atRadiusCap) {
        // Exhausted at max radius — feed is genuinely done.
        setHasMore(false);
        return;
      }

      setIsFetchingMore(true);
      setHasAttemptedLoadMore(true);
      try {
        const { lat, lng, queryRadius } = locationRef.current;
        // Within the current tier: page forward with the cursor.
        // Tier drained: widen the radius and re-query from the SAME cursor —
        // the keyset predicate excludes all already-seen rows, so a wider net
        // can only surface farther items (no dupes, no skips).
        const usingCursor = canPageCurrentTier ? nearbyCursor : nearbyCursor;
        const radius = canPageCurrentTier ? queryRadius : nextRadiusStep(queryRadius);

        const result = await fetchNearbyListings({
          lat,
          lng,
          radius,
          postType: productType,
          cursor: usingCursor,
        });

        if (result.success) {
          if (result.data.length > 0) {
            appendDeduped(result.data);
          }
          locationRef.current = { lat, lng, queryRadius: radius };
          setHasMore(result.hasMore);
          setNearbyCursor(result.nextCursor);

          // Tier drained but a larger radius remains: keep infinite scroll
          // armed so the next trigger expands the net again.
          if (!result.hasMore && radius < MAX_RADIUS_METERS) {
            setHasMore(true);
          }
        }
      } finally {
        setIsFetchingMore(false);
      }
      return;
    }

    // Non-location mode: id-based keyset pagination (separate cursor scheme).
    if (hasMore && productsCursor !== null) {
      setIsFetchingMore(true);
      setHasAttemptedLoadMore(true);
      try {
        const result = await fetchProductsPaginated(productType, productsCursor);
        if (result.success) {
          setExtraProducts((prev) => {
            const existingIds = new Set([...baseProducts, ...prev].map((p) => p.id));
            const newProducts = result.data.filter((p) => !existingIds.has(p.id));
            return [...prev, ...newProducts];
          });
          setHasMore(result.hasMore);
          setProductsCursor(result.nextCursor);
        }
      } finally {
        setIsFetchingMore(false);
      }
    }
  }, [
    isFetchingMore,
    hasMore,
    nearbyCursor,
    productsCursor,
    effectiveIsLocationFiltered,
    productType,
    appendDeduped,
  ]);

  // Auto-detect location on mount
  useEffect(() => {
    // Skip if URL already has location params (server already rendered nearby data)
    if (searchParams.has("lat") && searchParams.has("lng")) {
      return;
    }

    // If we have stored location, use it immediately via Server Action
    if (userLocation) {
      const radius = geoDistance || radiusMeters;

      // Update URL for shareability without triggering navigation
      const newParams = new URLSearchParams(searchParams.toString());
      newParams.set("lat", userLocation.latitude.toFixed(6));
      newParams.set("lng", userLocation.longitude.toFixed(6));
      newParams.set("radius", radius.toString());
      window.history.replaceState({}, "", `?${newParams.toString()}`);

      setTimeout(() => {
        fetchNearby(userLocation.latitude, userLocation.longitude, radius, productType);
      }, 0);
      return;
    }

    // Request browser geolocation
    if (navigator?.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          const radius = geoDistance || radiusMeters;

          // Store in Zustand for future visits
          setUserLocation({ latitude, longitude });

          // Update URL for shareability without triggering navigation
          const newParams = new URLSearchParams(searchParams.toString());
          newParams.set("lat", latitude.toFixed(6));
          newParams.set("lng", longitude.toFixed(6));
          newParams.set("radius", radius.toString());
          window.history.replaceState({}, "", `?${newParams.toString()}`);

          // Fetch nearby posts via Server Action
          fetchNearby(latitude, longitude, radius, productType);
        },
        (_error) => {
          // Silently fail - user will see all posts instead of nearby
        },
        {
          enableHighAccuracy: false,
          timeout: 10000,
          maximumAge: 300000, // 5 minutes cache
        }
      );
    }
  }, [
    searchParams,
    userLocation,
    setUserLocation,
    geoDistance,
    fetchNearby,
    productType,
    radiusMeters,
  ]);

  return (
    <>
      <NavigateButtons title="Show map" />
      <ProductGrid
        products={products}
        isLoading={isFetchingNearby}
        onLoadMore={handleLoadMore}
        isFetchingMore={isFetchingMore}
        hasMore={effectiveHasMore}
      />
      {effectiveIsLocationFiltered &&
        effectiveNearbyPosts &&
        effectiveNearbyPosts.length === 0 &&
        !isFetchingNearby && (
          <div className="text-center py-8 text-muted-foreground">
            Nothing shared within {formatDistance(clientRadius, locale)} yet — be the first to post
            in your area!
          </div>
        )}
    </>
  );
}

export default HomeClient;

"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import type { Session } from "@supabase/supabase-js";
import { z } from "zod";
import { createClient } from "@/lib/supabase/server";
import { CACHE_TAGS } from "@/lib/data/cache-keys";
import { invalidateTag } from "@/lib/data/cache-invalidation";
import { trackEvent } from "@/app/actions/analytics";
import { createActionLogger } from "@/lib/structured-logger";

// Import AuthUser for internal use (don't re-export from server action files)
import type { AuthUser } from "@/lib/data/auth";

// ============================================================================
// Validation Schemas
// ============================================================================

const emailSchema = z
  .string()
  .min(1, "Email is required")
  .email("Invalid email format")
  .max(254, "Email too long");

const passwordSchema = z
  .string()
  .min(8, "Password must be at least 8 characters")
  .max(128, "Password too long");

const signInSchema = z.object({
  email: emailSchema,
  password: z.string().min(1, "Password is required").max(128, "Password too long"),
});

const signUpSchema = z.object({
  email: emailSchema,
  password: passwordSchema,
  firstName: z.string().max(100, "First name too long").optional().nullable(),
  lastName: z.string().max(100, "Last name too long").optional().nullable(),
  name: z.string().max(200, "Name too long").optional().nullable(),
});

const updatePasswordSchema = z.object({
  password: passwordSchema,
});

/**
 * Check if a string is a full URL (http/https)
 */
function isFullUrl(url: string): boolean {
  return url.startsWith("http://") || url.startsWith("https://");
}

/**
 * Resolve avatar URL to a public URL
 * If it's already a full URL, return as-is
 * If it's a storage path, generate the public URL
 */
async function resolveAvatarUrl(
  supabase: Awaited<ReturnType<typeof createClient>>,
  avatarUrl: string | null
): Promise<string | null> {
  if (!avatarUrl || avatarUrl.trim() === "") return null;

  // If already a full URL, return as-is
  if (isFullUrl(avatarUrl)) return avatarUrl;

  // Otherwise, it's a storage path - get the public URL
  const { data } = supabase.storage.from("profiles").getPublicUrl(avatarUrl);
  return data?.publicUrl || null;
}

/**
 * Get current session
 * Returns null if not authenticated or DB is unavailable (graceful degradation)
 *
 * SECURITY: Uses getUser() which validates the JWT against the auth server,
 * unlike getSession() which only reads from cookies without verification.
 * See: https://supabase.com/docs/guides/auth/server-side/nextjs#understanding-the-authentication-flow
 */
export async function getSession(): Promise<Session | null> {
  try {
    const supabase = await createClient();
    // Validate the user's JWT against the auth server first
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) return null;

    // Only return the session if the user is verified
    const {
      data: { session },
      error,
    } = await supabase.auth.getSession();
    if (error) return null;
    return session;
  } catch {
    // DB unavailable - return null gracefully
    return null;
  }
}

/**
 * Get current user with profile
 * Returns null if DB is unavailable (graceful degradation)
 * Resolves avatar_url to a public URL if it's a storage path
 */
export async function getUser(): Promise<AuthUser | null> {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    // Auth error or no user = return null gracefully
    if (authError || !user) return null;

    // Get profile data - also wrapped in try-catch
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("id,first_name,second_name,nickname,avatar_url,email,search_radius_km")
        .eq("id", user.id)
        .single();

      // Resolve avatar URL to public URL if needed
      const resolvedAvatarUrl = profile?.avatar_url
        ? await resolveAvatarUrl(supabase, profile.avatar_url)
        : null;

      return {
        id: user.id,
        email: user.email,
        profile: profile
          ? {
              ...profile,
              avatar_url: resolvedAvatarUrl,
            }
          : null,
      };
    } catch {
      // Profile fetch failed, return user without profile
      return {
        id: user.id,
        email: user.email,
        profile: null,
      };
    }
  } catch {
    // DB unavailable - return null gracefully
    return null;
  }
}

/**
 * Check if current user is admin
 * Uses centralized admin auth from @/lib/data/admin-check
 * Returns false if DB is unavailable (graceful degradation)
 */
export async function checkUserIsAdmin(): Promise<boolean> {
  try {
    const { getAdminAuth } = await import("@/lib/data/admin-check");
    const { isAdmin } = await getAdminAuth();
    return isAdmin;
  } catch {
    return false;
  }
}

/**
 * Sign in with email and password
 */
export async function signInWithPassword(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  const logger = await createActionLogger("signInWithPassword");

  // Validate input
  const rawData = {
    email: formData.get("email"),
    password: formData.get("password"),
  };

  const validation = signInSchema.safeParse(rawData);
  if (!validation.success) {
    const firstError = validation.error.issues[0];
    logger.warn("Validation failed", { error: firstError?.message });
    return { success: false, error: firstError?.message || "Invalid input" };
  }

  const { email, password } = validation.data;
  const supabase = await createClient();

  const { error } = await supabase.auth.signInWithPassword({
    email,
    password,
  });

  if (error) {
    logger.warn("Sign in failed", { error: error.message });
    return { success: false, error: error.message };
  }

  revalidatePath("/", "layout");
  invalidateTag(CACHE_TAGS.AUTH);

  // Track login
  await trackEvent("User Login", { method: "password" });

  logger.info("User signed in successfully");
  return { success: true };
}

/**
 * Sign up with email and password
 */
export async function signUp(formData: FormData): Promise<{ success: boolean; error?: string }> {
  const logger = await createActionLogger("signUp");

  // Validate input
  const rawData = {
    email: formData.get("email"),
    password: formData.get("password"),
    firstName: formData.get("firstName") || null,
    lastName: formData.get("lastName") || null,
    name: formData.get("name") || null,
  };

  const validation = signUpSchema.safeParse(rawData);
  if (!validation.success) {
    const firstError = validation.error.issues[0];
    logger.warn("Validation failed", { error: firstError?.message });
    return { success: false, error: firstError?.message || "Invalid input" };
  }

  const { email, password, firstName, lastName, name } = validation.data;
  const supabase = await createClient();

  // Build display name from firstName/lastName or use name directly
  const displayName = firstName && lastName ? `${firstName} ${lastName}` : firstName || name || "";

  const { data, error } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: {
        name: displayName,
        first_name: firstName,
        last_name: lastName,
      },
    },
  });

  if (error) {
    logger.warn("Sign up failed", { error: error.message });
    return { success: false, error: error.message };
  }

  // Create profile (aligned with iOS AuthenticationService.createUserProfile)
  // Backend now handles this robustly via handle_new_user Postgres trigger
  // Wait, no need to insert here!

  revalidatePath("/", "layout");
  invalidateTag(CACHE_TAGS.AUTH);
  invalidateTag(CACHE_TAGS.PROFILES);

  // Track signup
  await trackEvent("User Signup", { method: "password" });

  logger.info("User signed up successfully");
  return { success: true };
}

/**
 * Sign out and redirect
 */
export async function signOut(): Promise<void> {
  const supabase = await createClient();
  await supabase.auth.signOut();
  revalidatePath("/", "layout");
  invalidateTag(CACHE_TAGS.AUTH);
  redirect("/");
}

/**
 * Request password reset
 */
export async function resetPassword(email: string): Promise<{ success: boolean; error?: string }> {
  // Validate email
  const validation = emailSchema.safeParse(email);
  if (!validation.success) {
    const firstError = validation.error.issues[0];
    return { success: false, error: firstError?.message || "Invalid email" };
  }

  const supabase = await createClient();

  const { error } = await supabase.auth.resetPasswordForEmail(validation.data, {
    redirectTo: `${process.env.NEXT_PUBLIC_SITE_URL}/auth/callback?type=recovery`,
  });

  if (error) {
    return { success: false, error: error.message };
  }

  return { success: true };
}

/**
 * Update password (for authenticated users)
 */
export async function updatePassword(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  // Validate input
  const rawData = {
    password: formData.get("password"),
  };

  const validation = updatePasswordSchema.safeParse(rawData);
  if (!validation.success) {
    const firstError = validation.error.issues[0];
    return { success: false, error: firstError?.message || "Invalid password" };
  }

  const supabase = await createClient();

  const { error } = await supabase.auth.updateUser({
    password: validation.data.password,
  });

  if (error) {
    return { success: false, error: error.message };
  }

  return { success: true };
}

/**
 * Get OAuth sign in URL
 */
export async function getOAuthSignInUrl(
  provider: "google" | "github" | "facebook" | "apple"
): Promise<{ url: string | null; error?: string }> {
  const supabase = await createClient();

  const { data, error } = await supabase.auth.signInWithOAuth({
    provider,
    options: {
      redirectTo: `${process.env.NEXT_PUBLIC_SITE_URL}/auth/callback`,
      // Must be true: this runs server-side as a Server Action,
      // so we return the URL to the client for navigation
      skipBrowserRedirect: true,
    },
  });

  if (error) {
    // Provide user-friendly error for missing OAuth configuration
    if (
      error.message.includes("missing OAuth secret") ||
      error.message.includes("Unsupported provider")
    ) {
      return {
        url: null,
        error: `${provider.charAt(0).toUpperCase() + provider.slice(1)} sign-in is not configured yet. Please use email/password or magic link.`,
      };
    }
    return { url: null, error: error.message };
  }

  return { url: data.url };
}

"use server";

/**
 * Feedback Server Actions
 * Bleeding-edge implementation with:
 * - Zod schema validation
 * - Type-safe action results
 * - Audit logging
 * - Proper admin auth via user_roles
 */

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { serverActionError, successVoid, type ServerActionResult } from "@/lib/errors";
import type { ErrorCode } from "@/lib/errors";
import { CACHE_TAGS } from "@/lib/data/cache-keys";
import { invalidateTag } from "@/lib/data/cache-invalidation";
import { requireAdmin } from "@/lib/data/admin-check";
import { createAdminClient } from "@/lib/supabase/admin";

// ============================================================================
// Zod Schemas
// ============================================================================

const FeedbackTypeSchema = z.enum(["bug", "feature", "general", "complaint"]);
const FeedbackStatusSchema = z.enum(["new", "in_progress", "resolved", "closed"]);

const SubmitFeedbackSchema = z.object({
  profile_id: z.string().uuid().optional().nullable(),
  name: z.string().min(1, "Name is required").max(100),
  email: z.string().email("Invalid email address"),
  subject: z.string().min(1, "Subject is required").max(200),
  message: z.string().min(10, "Message must be at least 10 characters").max(5000),
  feedback_type: FeedbackTypeSchema,
});

// ============================================================================
// Types
// ============================================================================

export type FeedbackType = z.infer<typeof FeedbackTypeSchema>;
export type FeedbackStatus = z.infer<typeof FeedbackStatusSchema>;

export interface FeedbackSubmission {
  profile_id?: string | null;
  name: string;
  email: string;
  subject: string;
  message: string;
  feedback_type: FeedbackType;
}

export interface FeedbackRecord extends FeedbackSubmission {
  id: string;
  status: FeedbackStatus;
  created_at: string;
  updated_at: string;
}

// Removed manual verifyAdminAccess in favor of requireAdmin() from admin-check.ts

// ============================================================================
// Audit Logging Helper
// ============================================================================

async function logAuditEvent(
  supabase: Awaited<ReturnType<typeof createClient>>,
  userId: string,
  action: string,
  resourceType: string,
  resourceId: string,
  metadata?: Record<string, unknown>
): Promise<void> {
  try {
    await supabase.rpc("log_audit_event", {
      p_user_id: userId,
      p_action: action,
      p_resource_type: resourceType,
      p_resource_id: resourceId,
      p_metadata: metadata || {},
    });
  } catch (err) {
    console.warn(`[audit] Failed to log: ${action} ${resourceType}:${resourceId}`, err);
  }
}

// ============================================================================
// Public Actions
// ============================================================================

/**
 * Submit new feedback (public)
 */
export async function submitFeedback(
  feedback: FeedbackSubmission
): Promise<ServerActionResult<FeedbackRecord>> {
  try {
    // Validate input
    const validated = SubmitFeedbackSchema.safeParse(feedback);
    if (!validated.success) {
      const firstError = validated.error.issues[0];
      return serverActionError(firstError.message, "VALIDATION_ERROR");
    }

    const supabase = await createClient();

    const { data, error } = await supabase
      .from("feedback")
      .insert({
        profile_id: validated.data.profile_id || null,
        name: validated.data.name,
        email: validated.data.email,
        subject: validated.data.subject,
        message: validated.data.message,
        feedback_type: validated.data.feedback_type,
        status: "new",
      })
      .select()
      .single();

    if (error) {
      console.error("Failed to submit feedback:", error);
      return serverActionError(error.message, "DATABASE_ERROR");
    }

    revalidatePath("/admin/feedback");
    invalidateTag(CACHE_TAGS.ADMIN);

    return {
      success: true,
      data: data as FeedbackRecord,
    };
  } catch (error) {
    console.error("Failed to submit feedback:", error);
    return serverActionError("Failed to submit feedback", "UNKNOWN_ERROR");
  }
}

/**
 * Get user's own feedback submissions
 */
export async function getUserFeedback(
  userId: string
): Promise<ServerActionResult<FeedbackRecord[]>> {
  try {
    // Validate ID
    if (!userId || !z.string().uuid().safeParse(userId).success) {
      return serverActionError("Invalid user ID", "VALIDATION_ERROR");
    }

    const supabase = await createClient();

    // Verify user is requesting their own feedback
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user || user.id !== userId) {
      return serverActionError("You can only view your own feedback", "FORBIDDEN");
    }

    const { data, error } = await supabase
      .from("feedback")
      .select("*")
      .eq("profile_id", userId)
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Failed to get user feedback:", error);
      return serverActionError(error.message, "DATABASE_ERROR");
    }

    return {
      success: true,
      data: (data ?? []) as FeedbackRecord[],
    };
  } catch (error) {
    console.error("Failed to get user feedback:", error);
    return serverActionError("Failed to get feedback", "UNKNOWN_ERROR");
  }
}

// ============================================================================
// Admin Actions
// ============================================================================

/**
 * Get all feedback (admin only)
 */
export async function getAllFeedback(): Promise<ServerActionResult<FeedbackRecord[]>> {
  try {
    await requireAdmin();
    const supabase = createAdminClient();

    const { data, error } = await supabase
      .from("feedback")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Failed to get all feedback:", error);
      return serverActionError(error.message, "DATABASE_ERROR");
    }

    return {
      success: true,
      data: (data ?? []) as FeedbackRecord[],
    };
  } catch (error) {
    console.error("Failed to get all feedback:", error);
    return serverActionError("Failed to get feedback", "UNKNOWN_ERROR");
  }
}

/**
 * Update feedback status (admin only)
 */
export async function updateFeedbackStatus(
  feedbackId: string,
  status: FeedbackStatus
): Promise<ServerActionResult<FeedbackRecord>> {
  try {
    // Validate inputs
    if (!feedbackId || !z.string().uuid().safeParse(feedbackId).success) {
      return serverActionError("Invalid feedback ID", "VALIDATION_ERROR");
    }

    const statusValidation = FeedbackStatusSchema.safeParse(status);
    if (!statusValidation.success) {
      return serverActionError("Invalid status", "VALIDATION_ERROR");
    }

    const adminId = await requireAdmin();
    const supabase = createAdminClient();

    const { data, error } = await supabase
      .from("feedback")
      .update({ status: statusValidation.data, updated_at: new Date().toISOString() })
      .eq("id", feedbackId)
      .select()
      .single();

    if (error) {
      console.error("Failed to update feedback status:", error);
      return serverActionError(error.message, "DATABASE_ERROR");
    }

    await logAuditEvent(supabase, adminId, "UPDATE_STATUS", "feedback", feedbackId, {
      newStatus: status,
    });

    revalidatePath("/admin/feedback");
    invalidateTag(CACHE_TAGS.ADMIN);

    return {
      success: true,
      data: data as FeedbackRecord,
    };
  } catch (error) {
    console.error("Failed to update feedback status:", error);
    return serverActionError("Failed to update feedback status", "UNKNOWN_ERROR");
  }
}

/**
 * Delete feedback (admin only)
 */
export async function deleteFeedback(feedbackId: string): Promise<ServerActionResult<void>> {
  try {
    // Validate ID
    if (!feedbackId || !z.string().uuid().safeParse(feedbackId).success) {
      return serverActionError("Invalid feedback ID", "VALIDATION_ERROR");
    }

    const adminId = await requireAdmin();
    const supabase = createAdminClient();

    const { error } = await supabase.from("feedback").delete().eq("id", feedbackId);

    if (error) {
      console.error("Failed to delete feedback:", error);
      return serverActionError(error.message, "DATABASE_ERROR");
    }

    await logAuditEvent(supabase, adminId, "DELETE", "feedback", feedbackId);

    revalidatePath("/admin/feedback");
    invalidateTag(CACHE_TAGS.ADMIN);

    return successVoid();
  } catch (error) {
    console.error("Failed to delete feedback:", error);
    return serverActionError("Failed to delete feedback", "UNKNOWN_ERROR");
  }
}

// ============================================================================
// Helper Actions
// ============================================================================

interface UserInfo {
  email: string | null;
  name: string | null;
  profileId: string | null;
}

/**
 * Get current user info for pre-filling feedback form
 */
export async function getCurrentUserInfo(): Promise<ServerActionResult<UserInfo | null>> {
  try {
    const supabase = await createClient();

    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return {
        success: true,
        data: null,
      };
    }

    const { data: profile } = await supabase
      .from("profiles")
      .select("first_name,second_name")
      .eq("id", user.id)
      .single();

    return {
      success: true,
      data: {
        email: user.email || null,
        name: profile
          ? [profile.first_name, profile.second_name].filter(Boolean).join(" ") || null
          : null,
        profileId: user.id,
      },
    };
  } catch (error) {
    console.error("Failed to get user info:", error);
    return serverActionError("Failed to get user info", "UNKNOWN_ERROR");
  }
}

