interface UserListingsClientProps {
  listings: InitialProductStateType[];
  user: AuthUser;
}

type FilterStatus = "all" | "active" | "inactive";
type SortOption = "newest" | "oldest" | "name" | "views";

const STATUS_OPTIONS = [
  { value: "all" as const, label: "All Status", icon: "🔘" },
  { value: "active" as const, label: "Active", icon: "✅" },
  { value: "inactive" as const, label: "Inactive", icon: "⏸️" },
];

const SORT_OPTIONS = [
  { value: "newest" as const, label: "Newest First", icon: "🕐" },
  { value: "oldest" as const, label: "Oldest First", icon: "📅" },
  { value: "name" as const, label: "Name (A-Z)", icon: "🔤" },
  { value: "views" as const, label: "Most Popular", icon: "👁️" },
];

export function UserListingsClient({ listings, user }: UserListingsClientProps) {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [filterStatus, setFilterStatus] = useState<FilterStatus>("all");
  const [filterType, setFilterType] = useState<string>("all");
  const [sortBy, setSortBy] = useState<SortOption>("newest");
  const [isLoaded, setIsLoaded] = useState(false);
  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      await refreshUserListingsCache(user.id);
      router.refresh();
    } finally {
      setIsRefreshing(false);
    }
  };

  // Trigger entrance animation
  useEffect(() => {
    setTimeout(() => {
      setIsLoaded(true);
    }, 0);
  }, []);

  const postTypes = [...new Set(listings.map((l) => l.post_type))];

  const filteredListings = listings
    .filter((listing) => {
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        if (
          !listing.post_name.toLowerCase().includes(query) &&
          !listing.post_description?.toLowerCase().includes(query)
        ) {
          return false;
        }
      }
      if (filterStatus === "active" && listing.is_active !== true) return false;
      if (filterStatus === "inactive" && listing.is_active !== false) return false;
      if (filterType !== "all" && listing.post_type !== filterType) return false;
      return true;
    })
    .sort((a, b) => {
      switch (sortBy) {
        case "newest":
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
        case "oldest":
          return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        case "name":
          return a.post_name.localeCompare(b.post_name);
        case "views":
          return (b.post_views || 0) - (a.post_views || 0);
        default:
          return 0;
      }
    });

  // Explicitly check for boolean true/false to handle potential null values
  const activeListings = listings.filter((l) => l.is_active === true);
  const inactiveListings = listings.filter((l) => l.is_active === false);
  const hasActiveFilters = searchQuery || filterStatus !== "all" || filterType !== "all";
  const activeFilterCount = [searchQuery, filterStatus !== "all", filterType !== "all"].filter(
    Boolean
  ).length;

  const clearFilters = () => {
    setSearchQuery("");
    setFilterStatus("all");
    setFilterType("all");
  };

  const currentSort = SORT_OPTIONS.find((o) => o.value === sortBy);
  const currentStatus = STATUS_OPTIONS.find((o) => o.value === filterStatus);

  // Mobile filter content (reusable)
  const FilterContent = () => (
    <div className="space-y-4">
      {/* Type Filter */}
      {postTypes.length > 0 && (
        <div>
          <label className="text-xs font-medium text-muted-foreground mb-2 block">Type</label>
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => {
                setFilterType("all");
                setMobileFiltersOpen(false);
              }}
              className={cn(
                "px-3 py-2 text-sm font-medium rounded-xl transition-all duration-200",
                filterType === "all"
                  ? "bg-emerald-600 text-white shadow-md shadow-emerald-500/25"
                  : "bg-muted/50 text-muted-foreground hover:bg-muted"
              )}
            >
              All
            </button>
            {postTypes.map((type) => (
              <button
                key={type}
                onClick={() => {
                  setFilterType(type);
                  setMobileFiltersOpen(false);
                }}
                className={cn(
                  "px-3 py-2 text-sm font-medium rounded-xl transition-all duration-200",
                  filterType === type
                    ? "bg-emerald-600 text-white shadow-md shadow-emerald-500/25"
                    : "bg-muted/50 text-muted-foreground hover:bg-muted"
                )}
              >
                {getPostTypeConfig(type).emoji} {getPostTypeConfig(type).label}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Status Filter */}
      <div>
        <label className="text-xs font-medium text-muted-foreground mb-2 block">Status</label>
        <div className="flex flex-wrap gap-2">
