/**
 * Table Logger
 * Beautiful table formatting for console output
 */

import { COLORS, STYLES, ANSI } from './styles';

const IS_BROWSER = typeof window !== 'undefined';

interface TableColumn {
  key: string;
  label?: string;
  width?: number;
  align?: 'left' | 'center' | 'right';
  format?: (value: unknown) => string;
}

/**
 * Format value for display
 */
function formatValue(value: unknown): string {
  if (value === null) return 'null';
  if (value === undefined) return '—';
  if (typeof value === 'boolean') return value ? '✓' : '✗';
  if (typeof value === 'number') return value.toLocaleString();
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return `[${value.length}]`;
  if (typeof value === 'object') return '{...}';
  return String(value);
}

/**
 * Pad string to width
 */
function pad(str: string, width: number, align: 'left' | 'center' | 'right' = 'left'): string {
  const len = str.length;
  if (len >= width) return str.slice(0, width);

  const padding = width - len;
  if (align === 'right') return ' '.repeat(padding) + str;
  if (align === 'center') {
    const left = Math.floor(padding / 2);
    const right = padding - left;
    return ' '.repeat(left) + str + ' '.repeat(right);
  }
  return str + ' '.repeat(padding);
}

/**
 * Browser table logging
 */
const browserTable = {
  /**
   * Log data as a styled table
   */
  log<T extends Record<string, unknown>>(
    title: string,
    data: T[],
    columns?: TableColumn[]
  ): void {
    if (data.length === 0) {
      console.log(`%c📊 ${title}: %cNo data`, `color: ${COLORS.purple}; font-weight: bold;`, `color: ${COLORS.muted};`);
      return;
    }

    // Auto-detect columns if not provided
    const cols: TableColumn[] = columns || Object.keys(data[0]).map(key => ({ key, label: key }));

    console.group(`%c📊 ${title}`, `color: ${COLORS.purple}; font-weight: bold;`);

    // Use native console.table for browser
    const tableData = data.map(row => {
      const formatted: Record<string, unknown> = {};
      cols.forEach(col => {
        const value = row[col.key];
        formatted[col.label || col.key] = col.format ? col.format(value) : formatValue(value);
      });
      return formatted;
    });

    console.table(tableData);
    console.log(`%c${data.length} rows`, `color: ${COLORS.muted}; font-size: 11px;`);
    console.groupEnd();
  },

  /**
   * Log key-value pairs as a vertical table
   */
  keyValue(title: string, data: Record<string, unknown>): void {
    console.group(`%c📋 ${title}`, `color: ${COLORS.purple}; font-weight: bold;`);

    Object.entries(data).forEach(([key, value]) => {
      const formattedValue = formatValue(value);
      const valueColor = typeof value === 'boolean' 
        ? (value ? COLORS.success : COLORS.error)
        : typeof value === 'number' 
          ? COLORS.cyan 
          : COLORS.dark;

      console.log(
        `%c${key}: %c${formattedValue}`,
        `color: ${COLORS.muted};`,
        `color: ${valueColor}; font-weight: 600;`
      );
    });

    console.groupEnd();
  },

  /**
   * Log a comparison table (before/after)
   */
  compare<T extends Record<string, unknown>>(
    title: string,
    before: T,
    after: T
  ): void {
    const allKeys = [...new Set([...Object.keys(before), ...Object.keys(after)])];

    console.group(`%c🔄 ${title}`, `color: ${COLORS.purple}; font-weight: bold;`);

    const tableData = allKeys.map(key => {
      const beforeVal = formatValue(before[key]);
      const afterVal = formatValue(after[key]);
      const changed = JSON.stringify(before[key]) !== JSON.stringify(after[key]);

      return {
        Property: key,
        Before: beforeVal,
        After: afterVal,
        Changed: changed ? '✓' : '',
      };
    });

    console.table(tableData);

    const changedCount = tableData.filter(r => r.Changed).length;
    console.log(`%c${changedCount} of ${allKeys.length} properties changed`, `color: ${COLORS.muted}; font-size: 11px;`);
    console.groupEnd();
  },

  /**
   * Log a summary/stats table
   */
  stats(title: string, stats: Record<string, number | string>): void {
    console.group(`%c📈 ${title}`, `color: ${COLORS.purple}; font-weight: bold;`);

    Object.entries(stats).forEach(([label, value]) => {
      const isNumber = typeof value === 'number';
      console.log(
        `%c${label} %c${isNumber ? value.toLocaleString() : value}`,
        `color: ${COLORS.muted}; min-width: 120px; display: inline-block;`,
        `color: ${COLORS.cyan}; font-weight: bold; font-size: 14px;`
      );
    });

    console.groupEnd();
  },

  /**
   * Log a tree structure
   */
  tree(title: string, data: Record<string, unknown>, depth = 0, maxDepth = 4): void {
    if (depth === 0) {
      console.group(`%c🌳 ${title}`, `color: ${COLORS.purple}; font-weight: bold;`);
    }

    const indent = '  '.repeat(depth);
    const entries = Object.entries(data);

    entries.forEach(([key, value], index) => {
      const isLast = index === entries.length - 1;
      const prefix = isLast ? '└─' : '├─';

      if (typeof value === 'object' && value !== null && !Array.isArray(value) && depth < maxDepth) {
        console.log(`%c${indent}${prefix} ${key}:`, `color: ${COLORS.purple};`);
        browserTable.tree('', value as Record<string, unknown>, depth + 1, maxDepth);
      } else {
        const formattedValue = formatValue(value);
        console.log(
          `%c${indent}${prefix} %c${key}: %c${formattedValue}`,
          `color: ${COLORS.muted};`,
          `color: ${COLORS.purple};`,
          `color: ${COLORS.cyan};`
        );
      }
    });

    if (depth === 0) {
      console.groupEnd();
    }
  },
};

/**
 * Server-side table logging
 */
const serverTable = {
  log<T extends Record<string, unknown>>(
    title: string,
    data: T[],
    columns?: TableColumn[]
  ): void {
    if (data.length === 0) {
      console.log(`${ANSI.magenta}📊 ${title}:${ANSI.reset} ${ANSI.gray}No data${ANSI.reset}`);
      return;
    }

    const cols: TableColumn[] = columns || Object.keys(data[0]).map(key => ({ key, label: key, width: 15 }));

    console.log(`\n${ANSI.magenta}${ANSI.bold}📊 ${title}${ANSI.reset}`);

    // Header
    const header = cols.map(col => pad(col.label || col.key, col.width || 15, col.align)).join(' │ ');
    const separator = cols.map(col => '─'.repeat(col.width || 15)).join('─┼─');

    console.log(`${ANSI.gray}┌─${separator.replace(/┼/g, '┬')}─┐${ANSI.reset}`);
    console.log(`${ANSI.gray}│ ${ANSI.bold}${header}${ANSI.reset}${ANSI.gray} │${ANSI.reset}`);
    console.log(`${ANSI.gray}├─${separator}─┤${ANSI.reset}`);

    // Rows
    data.forEach(row => {
      const rowStr = cols.map(col => {
        const value = row[col.key];
        const formatted = col.format ? col.format(value) : formatValue(value);
        return pad(formatted, col.width || 15, col.align);
      }).join(' │ ');
      console.log(`${ANSI.gray}│${ANSI.reset} ${rowStr} ${ANSI.gray}│${ANSI.reset}`);
    });

    console.log(`${ANSI.gray}└─${separator.replace(/┼/g, '┴')}─┘${ANSI.reset}`);
    console.log(`${ANSI.gray}${data.length} rows${ANSI.reset}\n`);
  },

  keyValue(title: string, data: Record<string, unknown>): void {
    console.log(`\n${ANSI.magenta}${ANSI.bold}📋 ${title}${ANSI.reset}`);

    const maxKeyLen = Math.max(...Object.keys(data).map(k => k.length));

    Object.entries(data).forEach(([key, value]) => {
      const paddedKey = key.padEnd(maxKeyLen);
      console.log(`  ${ANSI.gray}${paddedKey}${ANSI.reset} : ${ANSI.cyan}${formatValue(value)}${ANSI.reset}`);
    });
    console.log('');
  },

  compare<T extends Record<string, unknown>>(title: string, before: T, after: T): void {
    const allKeys = [...new Set([...Object.keys(before), ...Object.keys(after)])];

    console.log(`\n${ANSI.magenta}${ANSI.bold}🔄 ${title}${ANSI.reset}`);

    allKeys.forEach(key => {
      const beforeVal = formatValue(before[key]);
      const afterVal = formatValue(after[key]);
      const changed = JSON.stringify(before[key]) !== JSON.stringify(after[key]);

      if (changed) {
        console.log(`  ${ANSI.yellow}${key}${ANSI.reset}: ${ANSI.red}${beforeVal}${ANSI.reset} → ${ANSI.green}${afterVal}${ANSI.reset}`);
      } else {
        console.log(`  ${ANSI.gray}${key}: ${beforeVal}${ANSI.reset}`);
      }
    });
    console.log('');
  },

  stats(title: string, stats: Record<string, number | string>): void {
    console.log(`\n${ANSI.magenta}${ANSI.bold}📈 ${title}${ANSI.reset}`);

    Object.entries(stats).forEach(([label, value]) => {
      const formatted = typeof value === 'number' ? value.toLocaleString() : value;
      console.log(`  ${ANSI.gray}${label}:${ANSI.reset} ${ANSI.cyan}${ANSI.bold}${formatted}${ANSI.reset}`);
    });
    console.log('');
  },

  tree(title: string, data: Record<string, unknown>, depth = 0, maxDepth = 4): void {
    if (depth === 0) {
      console.log(`\n${ANSI.magenta}${ANSI.bold}🌳 ${title}${ANSI.reset}`);
    }

    const indent = '  '.repeat(depth + 1);
    const entries = Object.entries(data);

    entries.forEach(([key, value], index) => {
      const isLast = index === entries.length - 1;
      const prefix = isLast ? '└─' : '├─';

      if (typeof value === 'object' && value !== null && !Array.isArray(value) && depth < maxDepth) {
        console.log(`${indent}${ANSI.gray}${prefix}${ANSI.reset} ${ANSI.magenta}${key}:${ANSI.reset}`);
        serverTable.tree('', value as Record<string, unknown>, depth + 1, maxDepth);
      } else {
        console.log(`${indent}${ANSI.gray}${prefix}${ANSI.reset} ${ANSI.magenta}${key}:${ANSI.reset} ${ANSI.cyan}${formatValue(value)}${ANSI.reset}`);
      }
    });

    if (depth === 0) {
      console.log('');
    }
  },
};

/**
 * Table logger - auto-detects environment
 */
export const table = {
  log: <T extends Record<string, unknown>>(title: string, data: T[], columns?: TableColumn[]) =>
    IS_BROWSER ? browserTable.log(title, data, columns) : serverTable.log(title, data, columns),

  keyValue: (title: string, data: Record<string, unknown>) =>
    IS_BROWSER ? browserTable.keyValue(title, data) : serverTable.keyValue(title, data),

  compare: <T extends Record<string, unknown>>(title: string, before: T, after: T) =>
    IS_BROWSER ? browserTable.compare(title, before, after) : serverTable.compare(title, before, after),

  stats: (title: string, stats: Record<string, number | string>) =>
    IS_BROWSER ? browserTable.stats(title, stats) : serverTable.stats(title, stats),

  tree: (title: string, data: Record<string, unknown>, maxDepth?: number) =>
    IS_BROWSER ? browserTable.tree(title, data, 0, maxDepth) : serverTable.tree(title, data, 0, maxDepth),
};

export type { TableColumn };
export default table;

/**
 * Image Optimization Pipeline
 *
 * Provides WebP conversion, responsive sizing, and blur placeholder generation
 * Uses Sharp for high-performance image processing on the server.
 */

import sharp from "sharp";

// ============================================================================
// Types
// ============================================================================

export interface ImageSize {
  name: string;
  width: number;
  height?: number;
  quality?: number;
}

export interface OptimizedImage {
  buffer: Buffer;
  width: number;
  height: number;
  size: number;
  format: "webp" | "jpeg";
}

export interface ImageOptimizationResult {
  original: OptimizedImage;
  thumbnail?: OptimizedImage;
  medium?: OptimizedImage;
  large?: OptimizedImage;
  blurDataUrl?: string;
}

export interface OptimizationOptions {
  /** Generate thumbnail (64px) */
  thumbnail?: boolean;
  /** Generate medium size (480px) */
  medium?: boolean;
  /** Generate large size (1200px) */
  large?: boolean;
  /** Generate blur placeholder (20px base64) */
  blurPlaceholder?: boolean;
  /** Max width for original image (default: 1920) */
  maxWidth?: number;
  /** JPEG/WebP quality (default: 80) */
  quality?: number;
  /** Output format (default: webp) */
  format?: "webp" | "jpeg";
}

// ============================================================================
// Configuration
// ============================================================================

/** Standard image sizes for responsive loading */
export const IMAGE_SIZES: Record<string, ImageSize> = {
  thumbnail: { name: "thumbnail", width: 64, quality: 60 },
  medium: { name: "medium", width: 480, quality: 75 },
  large: { name: "large", width: 1200, quality: 80 },
  original: { name: "original", width: 1920, quality: 85 },
};

const DEFAULT_OPTIONS: Required<OptimizationOptions> = {
  thumbnail: true,
  medium: true,
  large: true,
  blurPlaceholder: true,
  maxWidth: 1920,
  quality: 80,
  format: "webp",
};

// ============================================================================
// Core Functions
// ============================================================================

/**
 * Optimize an image with multiple sizes and optional blur placeholder
 */
export async function optimizeImage(
  input: Buffer | ArrayBuffer | Uint8Array,
  options: OptimizationOptions = {}
): Promise<ImageOptimizationResult> {
  const opts = { ...DEFAULT_OPTIONS, ...options };
  const inputBuffer = Buffer.isBuffer(input) ? input : Buffer.from(input as ArrayBuffer);

  // Get original image metadata
  const metadata = await sharp(inputBuffer).metadata();
  const originalWidth = metadata.width || 1920;
  const originalHeight = metadata.height || 1080;

  // Process original (constrained to maxWidth)
  const original = await resizeAndConvert(inputBuffer, {
    width: Math.min(originalWidth, opts.maxWidth),
    quality: opts.quality,
    format: opts.format,
  });

  const result: ImageOptimizationResult = { original };

  // Generate sizes in parallel for performance
  const tasks: Promise<void>[] = [];

  if (opts.thumbnail) {
    tasks.push(
      resizeAndConvert(inputBuffer, {
        width: IMAGE_SIZES.thumbnail.width,
        quality: IMAGE_SIZES.thumbnail.quality,
        format: opts.format,
      }).then((img) => {
        result.thumbnail = img;
      })
    );
  }

  if (opts.medium && originalWidth > IMAGE_SIZES.medium.width) {
    tasks.push(
      resizeAndConvert(inputBuffer, {
        width: IMAGE_SIZES.medium.width,
        quality: IMAGE_SIZES.medium.quality,
        format: opts.format,
      }).then((img) => {
        result.medium = img;
      })
    );
  }

  if (opts.large && originalWidth > IMAGE_SIZES.large.width) {
    tasks.push(
      resizeAndConvert(inputBuffer, {
        width: IMAGE_SIZES.large.width,
        quality: IMAGE_SIZES.large.quality,
        format: opts.format,
      }).then((img) => {
        result.large = img;
      })
    );
  }

  if (opts.blurPlaceholder) {
    tasks.push(
      generateBlurPlaceholder(inputBuffer).then((dataUrl) => {
        result.blurDataUrl = dataUrl;
      })
    );
  }

  await Promise.all(tasks);

  return result;
}

/**
 * Resize and convert image to WebP/JPEG
 */
async function resizeAndConvert(
  input: Buffer,
  options: {
    width: number;
    height?: number;
    quality?: number;
    format?: "webp" | "jpeg";
  }
): Promise<OptimizedImage> {
  const { width, height, quality = 80, format = "webp" } = options;

  let pipeline = sharp(input).resize(width, height, {
    fit: "inside",
    withoutEnlargement: true,
  });

  if (format === "webp") {
    pipeline = pipeline.webp({ quality, effort: 4 });
  } else {
    pipeline = pipeline.jpeg({ quality, mozjpeg: true });
  }

  const { data, info } = await pipeline.toBuffer({ resolveWithObject: true });

  return {
    buffer: data,
    width: info.width,
    height: info.height,
    size: data.length,
    format,
  };
}

/**
 * Generate a tiny blur placeholder as base64 data URL
 */
export async function generateBlurPlaceholder(input: Buffer): Promise<string> {
  const blurBuffer = await sharp(input)
    .resize(20, 20, { fit: "inside" })
    .blur(2)
    .webp({ quality: 20 })
    .toBuffer();

  return `data:image/webp;base64,${blurBuffer.toString("base64")}`;
}

/**
 * Get image dimensions without full processing
 */
export async function getImageDimensions(
  input: Buffer | ArrayBuffer
): Promise<{ width: number; height: number }> {
  const inputBuffer = Buffer.isBuffer(input) ? input : Buffer.from(input);
  const metadata = await sharp(inputBuffer).metadata();
  return {
    width: metadata.width || 0,
    height: metadata.height || 0,
  };
}

/**
 * Validate image file before processing
 */
export function validateImageInput(
  input: Buffer | ArrayBuffer,
  maxSizeBytes: number = 10 * 1024 * 1024
): { valid: boolean; error?: string } {
  const size = input instanceof Buffer ? input.length : input.byteLength;

  if (size === 0) {
    return { valid: false, error: "Empty image data" };
  }

  if (size > maxSizeBytes) {
    return {
      valid: false,
      error: `Image too large (${Math.round(size / 1024 / 1024)}MB > ${Math.round(maxSizeBytes / 1024 / 1024)}MB)`,
    };
  }

  return { valid: true };
}

// ============================================================================
// Convenience Functions
// ============================================================================

/**
 * Quick optimize: Just convert to WebP with max dimensions
 */
export async function quickOptimize(
  input: Buffer | ArrayBuffer,
  maxWidth: number = 1920,
  quality: number = 80
): Promise<Buffer> {
  const inputBuffer = Buffer.isBuffer(input) ? input : Buffer.from(input);
  const result = await resizeAndConvert(inputBuffer, {
    width: maxWidth,
    quality,
    format: "webp",
  });
  return result.buffer;
}

/**
 * Create responsive image set for srcset
 */
export async function createResponsiveSet(input: Buffer | ArrayBuffer): Promise<{
  sizes: { width: number; buffer: Buffer }[];
  blurDataUrl: string;
}> {
  const inputBuffer = Buffer.isBuffer(input) ? input : Buffer.from(input);
  const metadata = await sharp(inputBuffer).metadata();
  const originalWidth = metadata.width || 1920;

  // Standard breakpoints
  const breakpoints = [320, 640, 768, 1024, 1280, 1536, 1920];
  const relevantBreakpoints = breakpoints.filter((bp) => bp <= originalWidth);

  const [sizes, blurDataUrl] = await Promise.all([
    Promise.all(
      relevantBreakpoints.map(async (width) => {
        const result = await resizeAndConvert(inputBuffer, { width, quality: 80 });
        return { width: result.width, buffer: result.buffer };
      })
    ),
    generateBlurPlaceholder(inputBuffer),
  ]);

  return { sizes, blurDataUrl };
}

/**
 * Circuit Breaker Tests
 *
 * Demonstrates testing the circuit breaker with enterprise test utilities.
 */

import { describe, it, expect, beforeEach } from "bun:test";
import {
  createTestCircuitBreaker,
  createFailingThenSucceedingFn,
} from "../enterprise-test-utils";
import { CircuitOpenError } from "../../api/circuit-breaker";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

describe("CircuitBreaker", () => {
  describe("state transitions", () => {
    it("should start in CLOSED state", () => {
      const breaker = createTestCircuitBreaker();
      const metrics = breaker.getMetrics();

      expect(metrics.state).toBe("CLOSED");
      expect(metrics.consecutiveFailures).toBe(0);
    });

    it("should transition to OPEN after failure threshold", async () => {
      const breaker = createTestCircuitBreaker({ failureThreshold: 2 });
      const failingFn = () => Promise.reject(new Error("fail"));

      // First failure
      await expect(breaker.execute(failingFn)).rejects.toThrow("fail");
      expect(breaker.getMetrics().state).toBe("CLOSED");

      // Second failure - should open circuit
      await expect(breaker.execute(failingFn)).rejects.toThrow("fail");
      expect(breaker.getMetrics().state).toBe("OPEN");
    });

    it("should reject immediately when OPEN", async () => {
      const breaker = createTestCircuitBreaker({ failureThreshold: 1 });

      // Open the circuit
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail")))
      ).rejects.toThrow("fail");

      // Should reject with CircuitOpenError
      await expect(
        breaker.execute(() => Promise.resolve("success"))
      ).rejects.toThrow(CircuitOpenError);
    });

    it("should transition to HALF_OPEN after reset timeout", async () => {
      const breaker = createTestCircuitBreaker({
        failureThreshold: 1,
        resetTimeoutMs: 50,
      });

      // Open the circuit
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail")))
      ).rejects.toThrow();

      expect(breaker.getMetrics().state).toBe("OPEN");

      // Wait past reset timeout
      await sleep(80);

      // Next call should be allowed (HALF_OPEN)
      const result = await breaker.execute(() => Promise.resolve("success"));
      expect(result).toBe("success");
      expect(breaker.getMetrics().state).toBe("CLOSED");
    });
  });

  describe("recovery", () => {
    it("should close circuit after successful call in HALF_OPEN", async () => {
      const breaker = createTestCircuitBreaker({
        failureThreshold: 1,
        resetTimeoutMs: 50,
        halfOpenRequests: 1,
      });

      // Open circuit
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail")))
      ).rejects.toThrow();

      // Wait for HALF_OPEN
      await sleep(80);

      // Successful call should close circuit
      await breaker.execute(() => Promise.resolve("success"));

      expect(breaker.getMetrics().state).toBe("CLOSED");
      expect(breaker.getMetrics().consecutiveFailures).toBe(0);
    });

    it("should reopen circuit on failure in HALF_OPEN", async () => {
      const breaker = createTestCircuitBreaker({
        failureThreshold: 1,
        resetTimeoutMs: 50,
      });

      // Open circuit
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail")))
      ).rejects.toThrow();

      // Wait for HALF_OPEN
      await sleep(80);

      // Failure should reopen circuit
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail again")))
      ).rejects.toThrow();

      expect(breaker.getMetrics().state).toBe("OPEN");
    });
  });

  describe("with retry pattern", () => {
    it("should work with failing-then-succeeding function", async () => {
      const breaker = createTestCircuitBreaker({ failureThreshold: 5 });
      const fn = createFailingThenSucceedingFn(2, "success");

      // First two calls fail
      await expect(breaker.execute(fn)).rejects.toThrow();
      await expect(breaker.execute(fn)).rejects.toThrow();

      // Third call succeeds
      const result = await breaker.execute(fn);
      expect(result).toBe("success");

      // Circuit should still be closed (under threshold)
      expect(breaker.getMetrics().state).toBe("CLOSED");
    });
  });

  describe("metrics", () => {
    it("should track success and failure counts", async () => {
      const breaker = createTestCircuitBreaker({ failureThreshold: 10 });

      // 3 successes
      await breaker.execute(() => Promise.resolve(1));
      await breaker.execute(() => Promise.resolve(2));
      await breaker.execute(() => Promise.resolve(3));

      // 2 failures
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail")))
      ).rejects.toThrow();
      await expect(
        breaker.execute(() => Promise.reject(new Error("fail")))
      ).rejects.toThrow();

      const metrics = breaker.getMetrics();
      expect(metrics.totalSuccesses).toBe(3);
      expect(metrics.totalFailures).toBe(2);
      expect(metrics.totalRequests).toBe(5);
    });
  });
});
